"""Private Besson 2002 main-article reader; no Site or publication side effects."""
from pathlib import Path
from collections import Counter
import json,hashlib,re
B=Path(__file__).resolve().parents[1];O=Path(__file__).resolve().parent
SID='besson2002';PAGE='besson2002';P='besson-2002-'
read=lambda p:json.loads(p.read_text(encoding='utf8'));sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
source=read(B/'source-manifest.json');manifest=read(B/'reader-assets/crop-manifest.json')
sections=[{'id':k,'title':v,'items':[]} for k,v in [('precursors','Precursors'),('protocol','Synthesis protocol'),('structures','Final structures'),('properties','Properties'),('intuition','Chemical intuition'),('sources','Sources and limitations')]];items={}
SCOPE={'source_cohort':'Source host, substrate and process-state cohort only. Shared methods do not establish the same physical specimen across techniques.','method_context':'Reported preparation or acquisition context; not an independently measured specimen property.','model_context':'Source interpretation or schematic, not a measured atomic structure or independently validated theory.','cited_context':'Context cited in this article; external cited documents were not independently inspected in this review.','source_metadata':'Bibliographic identity, coverage or administrative provenance, not a synthesis quantity.','author_outlook':'Proposed future work, not an executed synthesis or current measured outcome.','curator_interpretation':'Explicit source conflict or curation limit, kept separate from measured evidence.'}
ROUTES=['ctab-cds-loading','copolymer-cds-loading']
def ev(page,loc):return {'source_id':SID,'document_role':'main','pdf_page':page,'printed_page':408+page,'locator':f'Main PDF p. {page}, printed p. {408+page}, {loc}'}
def item(sec,key,title,text,page,loc,records=(),scope='source_cohort',kind='reported_source_fact',notes=()):
 assert key not in items,key
 e=ev(page,loc);d={'id':key,'title':title,'text':text,'claim_type':kind,'sample_scope':{'formulations':[],'physical_batch_id':None,'scope_kind':scope,'state':title,'link_limit':SCOPE[scope]},'evidence':[e],'source_locators':[e['locator']],'canonical_links':[{'record_id':P+k,'json_pointer':'','relation':SCOPE[scope]} for k in records],'notes':list(notes),'facts':[],'training_eligible':False}
 items[key]=d;next(s for s in sections if s['id']==sec)['items'].append(d);return d
def more(key,page,loc):
 e=ev(page,loc);items[key]['evidence'].append(e);items[key]['source_locators'].append(e['locator'])
def rows(sec,data):
 for x in data:item(sec,*x)

rows('precursors',[
('teos','Silica precursor','The matrix sol uses TEOS, written Si(OC₂H₅)₄, as the silica precursor. TEOS, acidic water and ethanol are combined in a 1:5:3.8 molar ratio. Reagent supplier, purity and absolute batch scale are not supplied. The final silica host is not the molecular TEOS precursor.',2,'Matrix preparation, lower left column',['ctab-silica-host'],'method_context'),
('water','Water and acidity','Water at pH 1.25 enters the matrix sol. Deionized water is used to rinse impregnated films. The acid identity, dose, water grade for other stock preparations and an explicit adjustment procedure for the acidic water are not given.',2,'Matrix preparation and impregnation procedure',['ctab-silica-host','cadmium-stock']+ROUTES,'method_context'),
('ethanol','Ethanol and dilution','Ethanol is a matrix-sol component at TEOS:H₂O:ethanol = 1:5:3.8 molar. After CTAB dissolution the sol is diluted with ethanol in a reported 1:1 ratio. The latter ratio has no stated mass, volume or mole basis; it is not converted into an exact solvent volume.',2,'Matrix preparation',['ctab-silica-host'],'method_context'),
('ctab','CTAB structure-directing agent','CTAB is dissolved in the aged sol at CTAB/TEOS = 0.1 mol/mol. It templates the mesoporous host and is removed by air calcination. The paper does not supply supplier, purity, micellar aggregation number or molecular coordinates for the template.',2,'Matrix preparation',['ctab-silica-host'],'method_context'),
('cadmium-nitrate','Cadmium nitrate','An aqueous cadmium nitrate solution at 0.1 M is the starting metal stock for impregnation. The source does not identify hydration state, supplier, purity, stock volume or a particular dissolved Cd coordination complex.',2,'Cadmium impregnation solution',['cadmium-stock']+ROUTES,'method_context'),
('ammonia','Ammonia ligand and pH adjustment','The cadmium solution receives one equivalent of ammonia and then additional ammonia until pH 9.5. The supplementary dose and ammonia stock concentration are not stated. Ammonia is a complexing/pH-control reagent here; no unique cadmium–ammine stoichiometry is established.',2,'Cadmium impregnation solution',['cadmium-stock'],'method_context'),
('citrate','Sodium citrate ligand','One equivalent of sodium citrate, supplied as a 1 M aqueous solution, is added to the cadmium nitrate solution. The exact sodium/protonation state and hydrate are not specified. The parenthetical 1 M concentration belongs to the sodium citrate solution; the text does not separately quantify an ammonia stock.',2,'Cadmium impregnation solution',['cadmium-stock'],'method_context'),
('hydrogen-sulfide','Hydrogen sulfide gas','Gaseous H₂S precipitates CdS inside the impregnated film after evacuation. It is introduced slowly until its pressure equals atmospheric pressure. Gas purity, numerical atmospheric pressure, delivery rate, exposure duration and a dissolved-sulfide reagent concentration are not supplied.',2,'Vacuum and H₂S precipitation',ROUTES,'method_context'),
('substrates','Pyrex and silicon substrates','The stated matrix procedure spin-coats Pyrex slides. A separate film on a silicon wafer is used for photoluminescence to avoid Pyrex luminescence. Neither a silicon wafer orientation nor a cleaning protocol is given. Silicon and glass are supports, not CdS precursors.',2,'Matrix deposition',['ctab-silica-host','pl-silicon'],'method_context'),
('copolymer','Unidentified triblock-copolymer template','A second host is templated by a triblock copolymer and has larger spherical pores. Its polymer identity, block composition, amount and complete host-preparation conditions are not supplied; reference 37 is only “to be published.” A known commercial polymer must not be substituted for this unidentified template.',2,'Larger-pore comparison', ['copolymer-cds-loading'],'curator_interpretation','reviewed_source_limitation'),
('stock-composition','Scope of the impregnation stock','The reported metal stock begins at 0.1 M cadmium nitrate, with one equivalent each of ammonia and sodium citrate plus extra ammonia for pH 9.5. The final concentration after all additions and the exact equivalence denominator are not numerically tabulated. Reagent equivalence and starting concentration are preserved without inventing a complete final-speciation formula.',2,'Cadmium impregnation solution',['cadmium-stock'],'method_context'),
])
more('substrates',5,'PL film on silicon to suppress substrate emission')

rows('protocol',[
('sol-mixing','Prepare the acidic silica sol','Combine TEOS, water at pH 1.25 and ethanol in a 1:5:3.8 molar ratio. The paper cites reference 29 for the earlier matrix procedure but supplies these conditions directly. Absolute volumes, acid identity, addition order and mixing speed are unreported.',2,'Matrix preparation',['ctab-silica-host'],'method_context'),
('sol-aging','Age the sol','Age the acidic sol for 1 h at 60 °C before dissolving CTAB. The aging temperature is a sol-processing condition, not the later CdS precipitation temperature; the heating apparatus and ramp are unspecified.',2,'Matrix preparation',['ctab-silica-host'],'method_context'),
('template-addition','Dissolve CTAB','Dissolve CTAB in the aged sol at a CTAB/TEOS molar ratio of 0.1. No dissolution duration, agitation rate or separate surfactant stock concentration is supplied.',2,'Matrix preparation',['ctab-silica-host'],'method_context'),
('ethanol-dilution','Dilute the templated sol','Dilute the resulting sol with ethanol at the stated 1:1 ratio. Its basis remains unspecified, so an illustrative equal-volume cartoon must not become a claimed source volume.',2,'Matrix preparation',['ctab-silica-host'],'method_context'),
('spin-coating','Spin-coat the matrix','Deposit the diluted sol on Pyrex slides by spin coating at 3,000 rpm. Coating duration, acceleration, dispensed volume, humidity, substrate dimensions and number of coating passes are not reported.',2,'Matrix preparation continuation',['ctab-silica-host'],'method_context'),
('calcination','Remove the organic template','Calcine the coated films in air at 450 °C to remove the surfactant. Calcination time, temperature ramp and cooling schedule are not given. The resulting film is reported to be approximately 300 nm thick with a textured 3D hexagonal pore arrangement.',2,'Matrix preparation continuation',['ctab-silica-host'],'method_context'),
('cadmium-stock-preparation','Prepare the complexing cadmium solution','Add one equivalent ammonia and one equivalent sodium citrate from a 1 M aqueous citrate stock to 0.1 M aqueous cadmium nitrate. Add further ammonia until pH 9.5. The source does not give a mixing duration, order between the first two additives, final volume or independently measured soluble-complex distribution.',2,'Cadmium impregnation solution',['cadmium-stock'],'method_context'),
('impregnation','Adsorb cadmium species inside the film','Impregnate the open mesoporous film with the basic aqueous cadmium solution. Cadmium adsorption is intended to occur on internal silica surfaces. Immersion duration, solution-to-film ratio, temperature, vessel and pressure during this liquid step are not quantified.',2,'Impregnation strategy and procedure',ROUTES,'method_context'),
('rinsing','Remove excess external solution','Wash the impregnated film with deionized water to remove excess cations and clean the film surface. The authors emphasize avoiding accumulation at the film–air interface and state no significant leaching for strongly bound Cd species. Wash volume, number and duration are unreported; no drying step is inserted.',2,'Rinsing strategy and procedure',ROUTES,'method_context'),
('evacuation','Evacuate before gas treatment','Place the rinsed film under vacuum before admitting H₂S. Vacuum level, evacuation time and apparatus dimensions are not reported. This step is distinct from the final atmospheric-pressure H₂S endpoint.',2,'Precipitation procedure',ROUTES,'method_context'),
('gas-precipitation','Precipitate CdS with gaseous H₂S','Inject H₂S gas slowly until P(H₂S) = P(atmosphere). The paper attributes uniform precipitation to rapid gas diffusion through the connected pore system. It does not state gas flow, hold time, numerical pressure, reaction temperature or a post-treatment purge.',2,'Precipitation procedure',ROUTES,'method_context'),
('ctab-cycles','Repeat the CTAB-film filling cycle','Repeat cadmium impregnation, rinsing and H₂S precipitation until saturation. The CTAB-film absorption series is reported to reach saturation after nine impregnation–precipitation cycles. The cycle number is a repeated process condition, not nine independently identified physical samples.',2,'CTAB-film absorption evolution',['ctab-cds-loading'],'method_context'),
('copolymer-cycles','Larger-pore comparison','The same general filling strategy is applied to a triblock-copolymer-templated matrix with larger pores. Figure 1c/d reaches a plotted six-cycle endpoint associated with the saturation discussion; six is read from the figure, while the prose does not independently state that cycle count. The copolymer host recipe remains incomplete.',2,'Copolymer-host comparison',['copolymer-cds-loading'],'method_context'),
('uv-acquisition','UV–visible absorption and optical sizing','Record absorption after filling cycles and infer mean CdS diameter from the gap–size correlations cited as reference 35. The source provides original spectra and size-trend plots, but no absorption-instrument model, complete numerical spectra, fitted gap table, uncertainty or full calibration equation.',2,'UV–visible results',['uv-visible'],'method_context'),
('xrd-acquisition','Low-angle X-ray diffraction','Measure films on an X’Pert Philips diffractometer using Cu Kα radiation in Bragg–Brentano geometry. Film texture selects the 0002 mesostructure reflection and its harmonic. Scan step, acquisition time, instrumental broadening and high-angle CdS phase refinement are not supplied.',2,'X-ray characterization',['xrd'],'method_context'),
('hrtem-acquisition','Cross-sectional high-resolution TEM','Examine the saturated film in cross section using a Topcon 002B at 200 kV with 0.18 nm point-to-point resolution. Images are slightly underfocused to enhance particle contrast. Cross-section preparation, specimen thickness and numerical defocus are unspecified. The stated microscope resolution is not a measured CdS fringe spacing.',3,'TEM methods at end of right column',['hrtem'],'method_context'),
('sims-acquisition','Depth-profile analysis','Secondary-ion mass spectrometry is reported for both a Cd²⁺-impregnated film and a CdS-saturated film. No instrument, sputtering conditions, depth calibration, count profiles or raw SIMS figure are supplied. The reported homogeneous Cd distribution is retained as a qualitative depth result.',2,'SIMS statement',['sims'],'method_context'),
('pl-acquisition','Photoluminescence on a silicon-supported film','Use a mesoporous film deposited on silicon to suppress Pyrex substrate emission, and measure emission and excitation spectra with a Hitachi F-4500 fluorescence spectrophotometer. Figure 4 states room temperature. Exact excitation/monitoring wavelengths, slit widths, detector corrections, lifetimes and absolute quantum yields are not reported.',4,'PL acquisition introduction',['pl-silicon'],'method_context'),
('loading-analysis','Estimate loading against a colloidal reference','Compare the maximum absorbance of the saturated film with a CdS colloidal reference having the same stated mean size of 3.5 nm. The comparison gives a 13% CdS volume fraction. Note 38 says the reference colloid was made by a reverse-micelle technique and cites reference 42; its full recipe and calibration values are not reproduced.',3,'Absorbance-based volume fraction',['loading-fraction'],'method_context'),
])
more('copolymer-cycles',3,'Figure 1c/d cycle labels');more('uv-acquisition',3,'Figure 1');more('pl-acquisition',5,'Silicon substrate and Figure 4 caption');more('loading-analysis',6,'Note 38')

rows('structures',[
('host-order','Textured 3D hexagonal silica host','The calcined CTAB-templated film has a 3D hexagonal mesostructure throughout its thickness, with the c-axis perpendicular to the substrate. These are pore-array coordinates, not atomic crystallographic dimensions of silica or CdS.',2,'Matrix preparation and texture',['ctab-silica-host']),
('host-thickness','Film thickness','The matrix and final CdS-loaded coating are described as approximately 300 nm thick. This is film thickness, distinct from the several-nanometer CdS crystallite size or the mesostructure lattice parameters.',2,'Matrix preparation continuation',['ctab-silica-host']),
('pore-estimate','Model-dependent pore diameter','Note 36 estimates an average pore diameter of 3.5 nm from porosity and an XRD-derived hexagonal unit-cell volume, assuming spherical pores. It is a geometrical pore estimate, not a direct TEM diameter of CdS crystallites or an exact atomistic cavity structure.',5,'Reference/Note 36',['ctab-silica-host'],'model_context','source_model_estimate'),
('ctab-size','CdS size in the CTAB-templated host','Optical gap–size correlations give an average CdS diameter increasing from 2.2 nm after the first filling cycle to 3.6 nm at saturation. These are optically inferred particle sizes. The 3.5 nm loading-reference size and model pore estimate are retained separately rather than substituted for the 3.6 nm endpoint.',2,'CTAB-film results',['ctab-cds-loading']),
('copolymer-size','CdS size in the larger-pore host','In the triblock-copolymer-templated host, the reported optically inferred CdS size grows from 3.3 nm after the first cycle to 5.8 nm at saturation. The larger spherical pores and 3D order are stated, but the polymer identity and a numerical host-pore diameter are absent.',2,'Copolymer comparison',['copolymer-cds-loading']),
('xrd-before-growth','Initial and cadmium-adsorbed host spacing','The low-angle XRD discussion gives c = 6.9 nm for the calcined film and 6.8 nm after Cd adsorption before the first H₂S treatment. The 0002 peak is described as about half as intense and shifted toward larger 2θ. The authors suggest high-pH silica condensation as a possible cause of the contraction.',2,'XRD discussion continuing onto next page',['xrd']),
('xrd-filling','Expansion during CdS filling','During filling the 0002 peak shifts to smaller 2θ; the source reports the mesostructure c parameter increasing from 6.8 nm before the first H₂S treatment to 7.2 nm in the saturated film. This is host-scale expansion, not a CdS atomic c lattice constant.',3,'XRD continuation',['xrd']),
('xrd-width','Persistence of ordered domains','No significant 0002 peak-width change is reported during intensity evolution. The authors infer that the size of ordered regions stays constant and growth preserves the mesostructure through the film. No numerical FWHM, Scherrer domain size or uncertainty is tabulated.',3,'XRD peak-width discussion',['xrd']),
('hrtem-filled-empty','Filled and empty films in cross section','Figure 3a shows dark CdS dots against a light background, while the empty calcined control in 3b shows bright pores against a darker silica background. The authors interpret this contrast reversal as consistent with filling and preserved order under matched imaging conditions. It is an empty/filled comparison, not proven before-and-after imaging of one physical specimen.',4,'Figure 3a/b and contrast discussion',['hrtem']),
('hrtem-empty-pores','Residual empty pores at the interface','The HRTEM discussion describes the film as filled throughout but identifies a few bright points near the film–substrate interface as empty pores. This qualification is retained alongside the reported 85% porosity-filling estimate; “filled” is not converted into a measured 100% occupancy.',4,'Figure 3a discussion',['hrtem']),
('cds-fringes','Atomic CdS lattice-fringe assignment','Some nanocrystals in the enlarged HRTEM image show 111 fringes assigned to blende-type CdS. The paper cites reference 39 for this size regime. No numeric fringe spacing, atomic lattice constant, refined phase fraction or independently measured orientation relationship is supplied.',4,'Figure 3c discussion',['hrtem']),
('image-power','Image Fourier power spectrum','Figure 3d is the power spectrum of the cross-sectional HRTEM image, defined in the text as |Fourier transform|². It supports a 3D hexagonal mesostructure assignment with P6₃/mmc symmetry, approximately a = 6.0 nm, c = 6.8 nm and c/a = 1.13. These are nanoparticle/pore superlattice parameters. The image is not a selected-area electron diffraction pattern.',4,'Figure 3d and power-spectrum paragraph',['hrtem']),
('mesostructure-comparison','Technique-specific mesostructure parameters','The Fourier-image discussion gives approximately c = 6.8 nm, whereas the saturated-film XRD discussion gives c = 7.2 nm. The article does not reconcile these values or identify exact common specimens. Both are retained with their technique and source context; no averaged parameter or false common refinement is introduced.',4,'Fourier-image parameters compared with p. 3 XRD',['xrd','hrtem'],'curator_interpretation','source_evidence_conflict'),
('host-vs-crystal','Mesostructure versus crystallite structure','CdS/SiO₂ identifies a composite, not a fixed whole-film stoichiometry or a core–shell molecular formula. The P6₃/mmc arrangement describes the mesoscopic pore/quantum-dot array, while 111 blende fringes concern atomic CdS crystallites inside those pores. Mesoscopic a and c in nanometers must not be presented as a CdS unit cell. The paper provides neither a complete atomic coordinate set nor a source-derived CIF for the composite.',4,'Figure 3 and structural discussion',['hrtem'],'curator_interpretation','curation_scope'),
('volume-fractions','CdS volume fraction and pore occupancy','The reported saturated-film CdS volume fraction is 13%, compared with a mesoporous volume fraction of 15% based on two pores per hexagonal unit cell. The authors report approximately 85% filling. These derived estimates depend on the optical comparator and pore model; the rounded values are not forced into a newly precise 13/15 result.',3,'Volume-fraction analysis',['loading-fraction'],'model_context','source_derived_estimate'),
('structure-limit','Structural data available for reuse','The original low-angle XRD pattern, cross-sectional HRTEM images, enlargement and image power spectrum are supplied. Raw diffraction arrays, atomic coordinates, a complete refined unit cell for CdS, SAED, tomography and an exact particle-by-particle occupancy list are not. No source-based measured atomic geometry is generated from the host lattice sketch.',4,'Supplied structural characterization',['hrtem','xrd'],'curator_interpretation','reviewed_source_limitation'),
])
more('host-thickness',5,'Conclusion: filled 300 nm film');more('xrd-before-growth',3,'Initial c = 6.9 to 6.8 nm');more('mesostructure-comparison',3,'XRD saturated c = 7.2 nm')

rows('properties',[
('color-sequence','Color changes during loading','A Cd²⁺-impregnated film is colorless. The first H₂S treatment makes it light yellow, and color intensity rises during subsequent impregnation–precipitation cycles. No calibrated color coordinates or absorbance-to-color conversion is reported.',2,'Loading observations',['ctab-cds-loading']),
('depth-uniformity','Cadmium depth distribution','SIMS is reported to show homogeneous Cd distribution through both the ion-impregnated film and the CdS-saturated film. The source does not provide a plotted depth profile, absolute Cd concentration or spatial-resolution limit. Homogeneous depth signal does not itself determine individual pore occupancy.',2,'SIMS statement',['sims']),
('ctab-absorption','Absorption in the CTAB host','CTAB-film absorption grows through the nine-cycle series and retains excitonic transitions, interpreted as a narrow particle-size distribution. No numerical standard deviation or size histogram is given. The optical diameter endpoints are 2.2 and 3.6 nm.',2,'Figure 1a/b discussion',['uv-visible']),
('copolymer-absorption','Absorption in the copolymer host','The larger-pore film has a red-shifted absorption edge compared with the CTAB host. Excitonic features are no longer visible after the second impregnation; the authors attribute this to weak confinement above approximately 5 nm. The source does not supply a quantitative polydispersity measurement for this comparison.',2,'Figure 1c/d discussion',['uv-visible']),
('figure1-spectra','Figure 1: original absorption curves','Panels a and c plot absorbance versus wavelength from 300 to 600 nm, with ordinate labels 0–0.5. CTAB panel a labels the calcined film and cycles 1, 2, 3, 4, 5, 7 and 9; copolymer panel c labels the calcined film and cycles 1, 2, 3, 4 and 6. The source spectra are preserved without redrawing or converting selected plotted cycles into an invented full raw data series.',3,'Figure 1a/c',['uv-visible']),
('figure1-sizes','Figure 1: optically inferred size trends','Panels b and d plot particle size in nm against number of impregnations. The CTAB curve reaches cycle nine and the copolymer curve cycle six. Intermediate marker heights remain source graphics, not exact newly transcribed diameters. The origin at zero cycles is a graphical baseline and is not a measured zero-diameter CdS sample.',3,'Figure 1b/d',['uv-visible']),
('figure2-axes','Figure 2: low-angle diffraction and scaling','The diffraction plot covers 2θ approximately 2.2–2.9° with intensity in arbitrary units. The calcined-film curve is scaled by 0.5 and the first-cycle curve by 5; these factors must accompany any visual intensity comparison. Cd²⁺-impregnated and later filling curves are labeled separately. No high-angle CdS diffraction pattern is displayed.',3,'Figure 2',['xrd']),
('figure3-panels','Figure 3: microscopy scale and reciprocal labels','Panels a and b have 30 nm scale bars; the enlargement c has a 20 nm scale bar. Panel d indexes mesostructure features as (0 0 0 2), (0 1 −1 1) and (0 1 −1 0), with overbars retained in the original image. It is an image-derived Fourier power spectrum without a printed calibrated reciprocal-length scale.',4,'Figure 3',['hrtem']),
('figure4-axes','Figure 4: excitation and luminescence','Figure 4 plots wavelength from 300 to 700 nm and intensity in arbitrary units. Dashed curves are excitation and solid curves emission, recorded at room temperature. The caption assigns upper curves to the first H₂S treatment and lower curves to subsequent Cd impregnation, but their visible spectral features conflict with the body’s sequence. No raw signal values or absolute calibration are supplied.',5,'Figure 4',['pl-silicon']),
('pl-first','Emission after the first H₂S exposure: prose assignment','The body assigns a weak broad band near 640 nm after the first H₂S treatment to surface-defect luminescence. This statement is retained as a prose-assigned process state; the conflicting upper/lower placement in Figure 4 is not silently reassigned.',5,'PL discussion',['pl-silicon']),
('pl-reimpregnation','Emission after the next Cd impregnation: prose assignment','The body reports stronger approximately 640 nm emission and a sharp 450 nm band after the next cadmium-solution impregnation. It assigns 450 nm to direct bound-exciton recombination and discusses surface passivation. The body-defined state is not relabeled as the caption’s upper curve without an uncertainty flag.',5,'PL discussion',['pl-silicon']),
('pl-later','Emission after further growth','After the second H₂S treatment and later impregnations, emission is reported to decrease and bound-exciton luminescence disappears. These later observations are described in the text without a complete plotted cycle series or numerical quantum-yield/lifetime table.',5,'PL discussion',['pl-silicon']),
('pl-figure-conflict','Unresolved Figure 4 process-state assignment','The caption places first-H₂S spectra above the subsequent-Cd spectra. The plotted upper emission curve has the stronger broad band and a sharp feature near 450 nm, whereas the body attributes those changes to subsequent Cd impregnation. The original figure and both textual assertions are retained; individual plotted curves are not converted into confidently labeled training examples.',5,'Figure 4 caption, visible curves and adjacent prose',['pl-silicon'],'curator_interpretation','source_evidence_conflict'),
])

rows('intuition',[
('nanoscale-context','Why control size and surfaces?','The introduction cites effects for nanocrystals below 10 nm, including local-field enhancement in metals, quantum confinement in semiconductors and superparamagnetism as motivation to control particle size, shape and surface state. These are literature examples, not additional measured properties of the present CdS/silica film.',1,'Introduction, references 1–4',['literature-context'],'cited_context'),
('array-motivation','Why organize particles in three dimensions?','The authors seek ordered particle arrays to study collective behavior and maximize nanocrystal filling in a solid matrix. They mention nonlinear optics, optoelectronics, biology and catalysis as application motivations. No collective optical response, biological assay or working device is measured in this paper.',1,'Introduction',['literature-context'],'cited_context'),
('template-rationale','Use an ordered porous host as a growth template','Condensing silica around surfactant or copolymer assemblies and removing the organic phase creates periodic pores. The introduction cites tunable mesopores of approximately 2–30 nm across the broader literature; that range is not the measured pore-size distribution of this film. The current host constrains both CdS size and spatial arrangement.',1,'Mesoporous template context',['chemical-intuition'],'model_context','author_interpretation'),
('film-motivation','Why films instead of porous powders?','The study targets nanoparticle-loaded coatings because they can be useful for optical applications. Earlier films made by MBE, CVD or silver growth are discussed with limitations in penetration, size control or order. The current result is a CdS-loaded silica coating; cited carbon/platinum replicas, nanowires, SiGe and silicon clusters are not additional syntheses performed here.',1,'Prior work and film motivation',['literature-context'],'cited_context'),
('ph-window','Balance cadmium adsorption and silica stability','The source proposes a pH window of 9–10: Cd adsorption onto silica is favorable above pH 9, whereas silica walls become partly soluble above pH 10. The chosen stock pH is 9.5. These rationale thresholds are not separate experimentally optimized recipes or a measured dissolution-rate curve in this work.',2,'General impregnation strategy',['chemical-intuition'],'model_context','author_interpretation'),
('complexation','Keep cadmium soluble during adsorption','Citrate and ammonia ligands maintain soluble cadmium species in the basic pH range and are intended to prevent hydroxide precipitation. The paper does not determine a unique solution complex, ligand-exchange constant or free-Cd²⁺ concentration; explanatory molecules are reference identities rather than measured species populations.',2,'Complexing-agent rationale',['chemical-intuition'],'model_context','author_interpretation'),
('surface-retention','Rinse excess ions while retaining adsorbed cadmium','The source attributes strong retention during rinsing to interactions with Si–O⁻ sites, while washing avoids excess cation buildup at the film–air interface. The no-significant-leaching statement is qualitative; no desorption isotherm or numerical loss fraction is presented.',2,'Rinsing rationale',['chemical-intuition'],'model_context','author_interpretation'),
('gas-diffusion','Use gas diffusion for homogeneous precipitation','H₂S gas is proposed to diffuse rapidly through the film and precipitate sulfide in the connected pores simultaneously. The authors argue that this avoids heterogeneity from isolated domains blocked by nanoparticles. A transport coefficient, pore-by-pore reaction movie or independently measured diffusion time is not supplied.',2,'Gas-treatment rationale',['chemical-intuition'],'model_context','author_interpretation'),
('silanol-regeneration','Regenerate adsorption sites for repeated filling','CdS precipitation is described as regenerating silanol sites at the pore surface, permitting renewed cadmium adsorption. Repeated loading fills the host more fully than the single-impregnation powder procedures cited in references 32–34. Surface regeneration is an author mechanism, not an in situ measured silanol-coverage series.',2,'Repeat-cycle rationale',['chemical-intuition'],'model_context','author_interpretation'),
('pore-size-control','Tune particle size through the template','The CTAB and copolymer hosts give different optical size endpoints, supporting pore-limited growth. The paper treats this as evidence that the matrix governs nanocrystal dimensions. It does not establish a universal predictive size equation or fully characterize the larger-pore host chemistry.',2,'Host comparison',['chemical-intuition'],'model_context','author_interpretation'),
('xrd-contrast','Interpret the changing 0002 intensity','Cd adsorption initially reduces silica–pore electron-density contrast. As dense CdS accumulates, contrast passes through a minimum and reverses; the 0002 peak then grows. The authors use this silica/air-to-silica/CdS contrast change as filling evidence. Intensity is not a direct scalar concentration without scattering and scaling assumptions.',3,'Scattering-contrast explanation',['chemical-intuition'],'model_context','author_interpretation'),
('host-deformation','Why does the mesostructure spacing change?','The initial contraction is tentatively associated with high-pH wall condensation; later expansion is attributed to pore deformation on filling. An earlier InP-filled powder study is cited as analogous behavior. These explanations are not a measured local stress field or a solved elastic model.',3,'XRD spacing explanation',['chemical-intuition'],'model_context','author_interpretation'),
('tem-contrast','Conditions behind the microscopy contrast comparison','HRTEM contrast depends on orientation, specimen thickness, lens defocus and accelerating voltage. The authors interpret filled/empty reversal assuming matched specimen thickness and imaging conditions, with identical underfocus. Their assignment remains conditional on those controls; dark contrast alone is not a quantitative composition map.',4,'Image-contrast discussion',['chemical-intuition'],'model_context','author_interpretation'),
('tem-orientation','Particle orientation and projection effects','Dark particles are attributed to zone-axis orientations producing strong Bragg diffraction. A small misorientation of the mesostructure [1 1 −2 0] direction relative to the beam and overlapping projected particles explains continuous gray regions. This does not establish a unique epitaxial orientation for every crystallite or a reconstructed 3D atomistic model.',4,'Figure 3c projection discussion',['chemical-intuition'],'model_context','author_interpretation'),
('pl-passivation','Interpret the two emission bands','The broad approximately 640 nm band is attributed to surface defects; its enhancement after Cd impregnation is associated with sulfur vacancies. A 450 nm band is assigned to a bound exciton and possible passivation by ammonia or hydroxyl groups, with references 40–41 cited. These are author assignments, not directly measured vacancy counts or resolved surface ligands.',5,'PL mechanism discussion',['chemical-intuition'],'model_context','author_interpretation'),
('pl-quenching','Why emission diminishes with later growth','The authors suggest that growth reduces surface accessibility and increases CdS–silica interactions, which can suppress direct exciton recombination. Reference 42 supports this interpretation. No quantitative quenching-rate model or lifetime series is reported for the filled films.',5,'Late-cycle emission discussion',['chemical-intuition'],'model_context','author_interpretation'),
('connected-porosity','Open porosity and repeated-cycle durability','Successful repeated filling is taken as evidence that the 3D mesoporous network is connected to the exterior and retains order during treatment. The authors contrast their coating-scale order with smaller colloidal assemblies cited in references 9 and 43. This does not quantify every pore connection or a maximum coherent domain area.',5,'Conclusion',['chemical-intuition'],'model_context','author_interpretation'),
('generalization','Proposed extension to other semiconductors','The authors suggest extending the chemical route to other sulfides or selenides, provided their cations can anchor to silica. These are proposed future material classes, not additional completed synthesis records or tested composition grids in this paper.',5,'Final conclusion',['chemical-intuition'],'author_outlook','author_outlook'),
])

rows('sources',[
('identity','Source identity','Sophie Besson, Thierry Gacoin, Christian Ricolleau, Catherine Jacquiod and Jean-Pierre Boilot, 3D Quantum Dot Lattice Inside Mesoporous Silica Films, Nano Letters 2002, 2(4), 409–414, DOI 10.1021/nl015685v. Received November 29, 2001; revised January 23, 2002; published online February 7, 2002.',1,'Title, byline, journal header and publication footer',[],'source_metadata','source_metadata'),
('source-context','Affiliations and administrative provenance','The byline lists École Polytechnique/CNRS, the CNRS–Saint-Gobain Surface du Verre et Interfaces laboratory and the mineralogy/crystallography laboratory of Universities Paris VI and VII. Jean-Pierre Boilot is corresponding author. The July 1, 2026 download watermark and PDF creation metadata are not synthesis or publication dates.',1,'Affiliations, footnote and watermark',[],'source_metadata','source_metadata'),
('coverage','Supplied-source coverage','All six main-article pages, four original figures, methods, figure captions and all 43 references/notes have been read and visually inspected. No supporting-information declaration was identified in the supplied main pages. No locally matched SI is claimed; this does not establish that SI cannot exist.',6,'Complete supplied main article',[],'source_metadata','reviewed_source_limitation'),
('method-dependencies','Cited methods and missing external documents','Matrix preparation cites reference 29, earlier host structure reference 30, optical size correlations reference 35 and the colloidal loading comparator note 38/reference 42. Those external documents were not independently read for this source review. Reference 37 is an unpublished copolymer-host dependency, not a complete identified recipe.',2,'Matrix and optical methods',['literature-context'],'cited_context','source_dependency'),
('copolymer-gap','Incomplete larger-pore host recipe','The triblock copolymer is unnamed, and no amount, composition or complete sol/film processing recipe is supplied for that host. The 60 °C aging, CTAB ratio and 450 °C calcination in the explicit CTAB route are not silently copied as verified copolymer-host conditions.',2,'Copolymer comparison and reference 37',['copolymer-cds-loading'],'curator_interpretation','reviewed_source_limitation'),
('unreported-fields','Unreported synthesis and acquisition details','The paper omits absolute sol scale, acid identity, ethanol-dilution basis, coating duration and volume, calcination schedule, impregnation duration, final complex-stock concentration, rinse schedule, evacuation level, H₂S rate/hold time, loading temperature, dry yield and storage. Raw SIMS, calibrated emission yields, lifetimes and atomic coordinates are also not supplied.',2,'Preparation and characterization methods',[],'curator_interpretation','reviewed_source_limitation'),
('sample-boundaries','Host, substrate and specimen boundaries','The CTAB and copolymer series are distinct host cohorts. The PL experiment explicitly uses a silicon-supported film, whereas the stated preparation uses Pyrex; a shared physical specimen is not assumed. Empty, Cd-adsorbed, first-cycle and saturated states remain distinct, and a reference colloid is not a pore-confined product.',3,'Figure 1–3 specimen contexts',['uv-visible','xrd','hrtem','pl-silicon','loading-fraction'],'curator_interpretation','curation_scope'),
('digitization-limit','Original curves and data precision','Original plots are shown with their axes, captions, scaling and process-state ambiguities. No dense raw spectral arrays, exact intermediate marker values, statistical size distributions or numerical diffraction-peak fits are reconstructed from the images. Published text endpoints remain distinct from visually read cycle labels.',3,'Figures 1–2',[],'curator_interpretation','curation_scope'),
('historical-scope','Scope of the reported result','The paper presents template-directed 3D CdS arrays over a coating-scale region and compares them with prior powders and colloidal assemblies. These are attributed 2002 conclusions; the present reader does not claim a new priority assessment or independently demonstrated device performance.',5,'Conclusion',['literature-context'],'cited_context','attributed_historical_claim'),
('acknowledgment','Research support','The work was supported by Saint-Gobain Recherche. T. Cretin is thanked for SIMS analyses. This is administrative provenance rather than an additional experimental condition.',5,'Acknowledgment',[],'source_metadata','source_metadata'),
])
